<template>
  <section class="handoff-shell">
    <header><div><small>{{ $t('clinical360.handoff.tab.shift_continuity') }}</small><h2>{{ $t('clinical360.handoff.tab.clinical_handoff') }}</h2><p>{{ $t('clinical360.handoff.tab.sbar_summary_note') }}</p></div><v-btn v-if="!readOnly" x-small depressed color="#0f766e" dark @click="$emit('new-handoff')"><v-icon x-small left>mdi-account-switch-outline</v-icon>{{ $t('clinical360.handoff.tab.document_handoff') }}</v-btn></header>
    <div class="sbar-grid">
      <article><b>S</b><div><strong>{{ $t('clinical360.handoff.tab.situation') }}</strong><p>{{ patient.patientClass || $t('clinical360.handoff.tab.patient_fallback') }} · {{ patient.bed || $t('clinical360.handoff.tab.bed_not_assigned') }}</p><span>{{ latestConcern }}</span></div></article>
      <article><b>B</b><div><strong>{{ $t('clinical360.handoff.tab.background') }}</strong><p>{{ patient.diagnosis || patient.primaryDiagnosis || $t('clinical360.handoff.tab.diagnosis_not_documented') }}</p><span>{{ patient.allergies || $t('clinical360.handoff.tab.allergies_require_verification') }}</span></div></article>
      <article><b>A</b><div><strong>{{ $t('clinical360.handoff.tab.assessment') }}</strong><p>{{ $t('clinical360.handoff.tab.open_diagnostic_orders', { count: openOrders }) }}</p><span>{{ $t('clinical360.handoff.tab.work_list_items_overdue', { count: tasks.length, overdue: overdueTasks }) }}</span></div></article>
      <article><b>R</b><div><strong>{{ $t('clinical360.handoff.tab.recommendation') }}</strong><p>{{ nextAction }}</p><span>{{ $t('clinical360.handoff.tab.incoming_team_acknowledge') }}</span></div></article>
    </div>
    <section class="open-items"><h3>{{ $t('clinical360.handoff.tab.unresolved_before_handoff') }}</h3><div v-if="!openItems.length" class="clear"><v-icon small color="#047857">mdi-check-circle</v-icon>{{ $t('clinical360.handoff.tab.no_unresolved_items') }}</div><div v-for="item in openItems" :key="item.id" class="item"><v-icon small :color="item.color">{{ item.icon }}</v-icon><strong>{{ item.title }}</strong><span>{{ item.detail }}</span></div></section>
  </section>
</template>
<script>
export default { name:'Patient360HandoffTab', props:{ patient:{type:Object,default:()=>({})}, notes:{type:Array,default:()=>[]}, tasks:{type:Array,default:()=>[]}, labOrders:{type:Array,default:()=>[]}, imagingOrders:{type:Array,default:()=>[]}, readOnly:Boolean }, computed:{ latestNote(){return [...this.notes].sort((a,b)=>new Date(b.recordedAt||b.createdAt)-new Date(a.recordedAt||a.createdAt))[0]||{}}, latestConcern(){return this.latestNote.observation||this.latestNote.body||this.$t('clinical360.handoff.tab.no_handoff_concern')}, openOrders(){return [...this.labOrders,...this.imagingOrders].filter(x=>!/complete|final|cancel/i.test(x.status||'')).length}, overdueTasks(){return this.tasks.filter(x=>/overdue/i.test(x.status||'')).length}, nextAction(){const t=this.tasks.find(x=>!/complete|done/i.test(x.status||''));return t?t.title||this.$t('clinical360.handoff.tab.complete_assigned_task'):this.$t('clinical360.handoff.tab.continue_surveillance')}, openItems(){const rows=[];if(this.openOrders)rows.push({id:'orders',icon:'mdi-clipboard-pulse-outline',color:'#b45309',title:this.$t('clinical360.handoff.tab.orders_pending',{count:this.openOrders}),detail:this.$t('clinical360.handoff.tab.review_collection_status')});this.tasks.filter(x=>!/complete|done/i.test(x.status||'')).slice(0,5).forEach((x,i)=>rows.push({id:x.id||`t${i}`,icon:'mdi-checkbox-marked-circle-auto-outline',color:x.status==='overdue'?'#be123c':'#0369a1',title:x.title||this.$t('clinical360.handoff.tab.care_task'),detail:`${x.assignedToRole||this.$t('clinical360.handoff.tab.care_team')} · ${x.status||this.$t('clinical360.handoff.tab.pending_status')}`}));return rows} } }
</script>
<style scoped>
.handoff-shell{padding:14px;background:#f8fbfb;min-height:100%}.handoff-shell>header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #0f766e;padding-bottom:10px}.handoff-shell small{font-weight:900;color:#64748b}.handoff-shell h2{font-size:18px;margin:2px 0}.handoff-shell p{margin:0}.sbar-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.sbar-grid article{display:flex;gap:10px;border:1px solid #cbd5e1;background:white;padding:11px}.sbar-grid b{display:grid;place-items:center;background:#0f766e;color:white;width:28px;height:28px}.sbar-grid strong{font-size:13px}.sbar-grid p,.sbar-grid span{font-size:12px}.sbar-grid span{color:#64748b}.open-items{margin-top:12px;border-top:1px solid #cbd5e1}.open-items h3{font-size:13px}.item,.clear{display:grid;grid-template-columns:24px minmax(180px,1fr) 2fr;gap:8px;padding:8px;border-bottom:1px solid #e2e8f0;font-size:12px}@media(max-width:700px){.sbar-grid{grid-template-columns:1fr}}
</style>
